  "Your name": "你的名字",
  "When were you born?": "你的出生日期？",
  "This helps us build your workout.": "这有助于我们制定你的训练。",
  "Which option best describes you?": "哪个选项最符合你？",
  "This may help improve nutrition, sleep and water estimates. It doesn’t change your workouts.": "这有助于改进营养、睡眠和饮水估算，不会改变你的训练。",
  "What’s your height?": "你的身高是多少？",
  "This will help with your nutrition guidance.": "这有助于你的营养指导。",
  "What’s your current weight?": "你目前的体重是多少？",
  "This helps choose your starting weights and gives us a benchmark to track your progress.": "这有助于选择你的起始重量，并为跟踪进度提供基准。",
  "Do you have a goal weight?": "你有目标体重吗？",
  "This is so you can track your progress. You can change it later.": "这样你就能跟踪进度。以后可以更改。",
  "What’s your main goal?": "你的主要目标是什么？",
  "This will help build your workout plan.": "这有助于制定你的训练计划。",
  "Anywhere you especially want to grow?": "有哪些部位你特别想增强？",
  "Choose up to two areas. This is optional.": "最多选择两个部位。此项为可选。",
  "How experienced are you with training?": "你的训练经验如何？",
  "Have you followed a structured training program before?": "你之前是否遵循过系统的训练计划？",
  "Which days can you train?": "你哪几天可以训练？",
  "Choose every day that could realistically work.": "选择所有实际可行的日子。",
  "You can always change your days later if things get busy.": "如果之后变忙，你随时可以更改日期。",
  "How long can you usually train?": "你通常能训练多久？",
  "This helps us shape your workout plan.": "这有助于我们规划你的训练计划。",
  "Do you usually train alone?": "你通常独自训练吗？",
  "This helps us decide your exercise selection and when someone may be able to help you.": "这有助于我们决定动作选择，以及何时可能有人帮到你。",
  "What equipment do you normally have access to?": "你通常能使用哪些器材？",
