  "A group always needs an owner. Pick a member to hand the group to, and you'll leave once they take over.": "एक ग्रुप को हमेशा एक मालिक की ज़रूरत होती है। ग्रुप सौंपने के लिए एक सदस्य चुनें, और जैसे ही वे संभालेंगे आप छोड़ देंगे।",
  "A planned rest day or a freeze token keeps your streak alive through an off day. You get 2 fresh freezes at each monthly reset, no guilt, no all-or-nothing.": "एक नियोजित आराम का दिन या फ़्रीज़ टोकन किसी छुट्टी वाले दिन आपकी स्ट्रीक को जीवित रखता है। हर मासिक रीसेट पर आपको 2 नए फ़्रीज़ मिलते हैं, कोई अपराधबोध नहीं, कोई 'सब या कुछ नहीं' वाला दबाव नहीं।",
