  "You're back in the running": "आप फिर से दौड़ में हैं",
  "You're first in. New lifters land here every day. Invite a friend and climb together.": "आप सबसे पहले हैं। हर दिन नए लिफ्टर यहाँ आते हैं। किसी दोस्त को आमंत्रित करें और साथ में ऊपर चढ़ें।",
  "You're in the top tier. Hold your rank to stay in {tier}.": "आप शीर्ष टियर में हैं। {tier} में बने रहने के लिए अपनी रैंक बनाए रखें।",
  "You're offline — changes are saved on this device and sync when you reconnect.": "आप ऑफ़लाइन हैं — बदलाव इस डिवाइस पर सहेजे जाते हैं और दोबारा कनेक्ट होने पर सिंक होते हैं।",
  "You're placed in a league with others at your level, up to ~25 as it fills. Your score is your dashboard odometer, how consistently you hit your goals. It's about showing up, not how much you lift.": "आपको आपके स्तर के अन्य लोगों के साथ एक लीग में रखा जाता है, भरने पर ~25 तक। आपका स्कोर आपका डैशबोर्ड ओडोमीटर है, यानी आप कितनी लगातार अपने लक्ष्य पूरे करते हैं। यह दिखने के बारे में है, न कि आप कितना उठाते हैं।",
  "You're previewing Community. Claim a name to join groups and appear on leaderboards.": "आप समुदाय का प्रीव्यू देख रहे हैं। ग्रुप में शामिल होने और लीडरबोर्ड पर दिखने के लिए एक नाम क्लेम करें।",
  "You're the only member, so leaving deletes this group for good.": "आप एकमात्र सदस्य हैं, इसलिए छोड़ने पर यह ग्रुप हमेशा के लिए हट जाएगा।",
  "Your BMI": "आपका BMI",
  "Your account has been deleted. If you had a subscription and did not cancel it, email info@strengthhubonline.com and we will cancel it.": "आपका खाता हटा दिया गया है। यदि आपकी सदस्यता थी और आपने उसे रद्द नहीं किया, तो info@strengthhubonline.com पर ईमेल करें और हम उसे रद्द कर देंगे।",
  "Your account is being deleted and access has been revoked. Some data is still being removed — this will finish automatically.": "आपका खाता हटाया जा रहा है और एक्सेस रद्द कर दी गई है। कुछ डेटा अब भी हटाया जा रहा है — यह स्वचालित रूप से पूरा हो जाएगा।",
  "Your coach": "आपका कोच",
  "Your coach is being reviewed by a qualified professional before it goes live. We’ll switch it on here once it’s ready.": "आपके कोच की समीक्षा लाइव होने से पहले एक योग्य पेशेवर द्वारा की जा रही है। तैयार होते ही हम इसे यहाँ चालू कर देंगे।",
  "Your data export is ready": "आपका डेटा एक्सपोर्ट तैयार है",
  "Your first 90 days": "आपके पहले 90 दिन",
  "Your league is filling up": "आपकी लीग भर रही है",
  "Your rank": "आपकी रैंक",
  "Your rank is paused while we double-check this week's activity. It usually clears on its own, so keep logging as normal.": "इस सप्ताह की गतिविधि की दोबारा जाँच करते समय आपकी रैंक रुकी हुई है। यह आमतौर पर अपने आप हट जाती है, इसलिए सामान्य रूप से लॉग करते रहें।",
  "Your standing is under review": "आपकी स्थिति समीक्षाधीन है",
  "Your stats": "आपके आँकड़े",
  "Your tracked lifts · Last {range}": "आपके ट्रैक किए गए लिफ्ट · पिछले {range}",
  "Your training profile becomes editable once onboarding is complete on a real account.": "किसी वास्तविक खाते पर ऑनबोर्डिंग पूरी होने के बाद आपकी प्रशिक्षण प्रोफ़ाइल संपादन योग्य हो जाती है।",
  "Your training won’t change for these dates. You can always add it again later.": "इन तारीखों के लिए आपका प्रशिक्षण नहीं बदलेगा। आप इसे बाद में कभी भी फिर से जोड़ सकते हैं।",
  "Your username is how friends find you and how you appear on every leaderboard.": "आपका उपयोगकर्ता नाम वह है जिससे दोस्त आपको ढूँढते हैं और जिससे आप हर लीडरबोर्ड पर दिखते हैं।",
