  "A full week-by-week program unlocks once you save your experience.": "अपना अनुभव सहेजते ही पूरा सप्ताह-दर-सप्ताह कार्यक्रम अनलॉक हो जाता है।",
  "Shaped around your goals, schedule and preferences, {name}.": "{name}, आपके लक्ष्यों, समय-सारणी और पसंद के अनुसार बनाया गया।",
