  "flagged area": "चिह्नित हिस्सा",
  "You mentioned this may need extra care. Just a few quick questions so we can work around it and see how we can help.": "आपने बताया कि इसे अतिरिक्त देखभाल की ज़रूरत हो सकती है। बस कुछ त्वरित सवाल ताकि हम इसके आसपास काम कर सकें और देख सकें कि कैसे मदद करें।",
  "StrengthHub provides general fitness information, not a medical assessment. This isn’t a diagnosis.": "StrengthHub सामान्य फ़िटनेस जानकारी देता है, कोई चिकित्सीय मूल्यांकन नहीं। यह निदान नहीं है।",
  "I’ll come back later": "मैं बाद में आऊँगा/आऊँगी",
  "Thanks for your interest in StrengthHub": "StrengthHub में आपकी रुचि के लिए धन्यवाद",
  "StrengthHub creates personalised training programs for people aged 18 and over. We can’t generate a program for you yet — but we’d love to have you when the time is right.": "StrengthHub 18 वर्ष और उससे अधिक आयु के लोगों के लिए वैयक्तिकृत प्रशिक्षण कार्यक्रम बनाता है। हम अभी आपके लिए कार्यक्रम नहीं बना सकते — लेकिन सही समय आने पर हम आपका स्वागत करना चाहेंगे।",
  "In the meantime, staying active with sport and everyday movement is a great foundation.": "इस बीच, खेल और रोज़मर्रा की गतिविधि से सक्रिय रहना एक बढ़िया आधार है।",
