  "We'll place your two maintenance sessions on the days that suit you.": "سنضع جلستَي الصيانة الخاصتين بك في الأيام التي تناسبك.",
  "We'll switch you back to your normal program automatically on {date}. Sessions you miss during this time won't count against you.": "سنعيدك تلقائيًا إلى برنامجك المعتاد في {date}. الجلسات التي تفوّتها خلال هذه الفترة لن تُحسب ضدّك.",
