  "You can still save the profile — the plan stays on hold until the block clears ({reason}).": "لا يزال بإمكانك حفظ الملف — تبقى الخطة معلّقة حتى يُرفع الحظر ({reason}).",
  "You have read them all": "لقد قرأتها كلها",
