  "You're all set": "أنت جاهز تمامًا",
  "You're back in the running": "لقد عدت إلى المنافسة",
  "You're first in. New lifters land here every day. Invite a friend and climb together.": "أنت أول من انضم. ينضم رافعون جدد هنا كل يوم. ادعُ صديقًا واصعدا معًا.",
  "You're in the top tier. Hold your rank to stay in {tier}.": "أنت في أعلى فئة. حافظ على رتبتك للبقاء في {tier}.",
  "You're offline — changes are saved on this device and sync when you reconnect.": "أنت غير متصل — تُحفظ التغييرات على هذا الجهاز وتتم المزامنة عند إعادة الاتصال.",
  "You're placed in a league with others at your level, up to ~25 as it fills. Your score is your dashboard odometer, how consistently you hit your goals. It's about showing up, not how much you lift.": "يتم وضعك في دوري مع آخرين في مستواك، حتى نحو 25 عند امتلائه. نتيجتك هي عدّاد الاتساق في لوحتك، أي مدى ثباتك في تحقيق أهدافك. الأمر يتعلق بالمواظبة، لا بمقدار ما ترفعه.",
  "You're previewing Community. Claim a name to join groups and appear on leaderboards.": "أنت تعاين المجتمع. احجز اسمًا للانضمام إلى المجموعات والظهور في لوحات المتصدرين.",
  "You're the only member, so leaving deletes this group for good.": "أنت العضو الوحيد، لذا فإن المغادرة تحذف هذه المجموعة نهائيًا.",
  "Your BMI": "مؤشر كتلة جسمك",
  "Your account has been deleted. If you had a subscription and did not cancel it, email info@strengthhubonline.com and we will cancel it.": "تم حذف حسابك. إذا كان لديك اشتراك ولم تقم بإلغائه، راسلنا على info@strengthhubonline.com وسنقوم بإلغائه.",
  "Your account is being deleted and access has been revoked. Some data is still being removed — this will finish automatically.": "يتم حذف حسابك وتم إلغاء الوصول. لا تزال بعض البيانات قيد الإزالة — سيكتمل ذلك تلقائيًا.",
  "Your coach": "مدربك",
  "Your coach is being reviewed by a qualified professional before it goes live. We’ll switch it on here once it’s ready.": "تتم مراجعة مدربك من قبل مختص مؤهّل قبل تفعيله. سنقوم بتشغيله هنا بمجرد أن يصبح جاهزًا.",
