  "This helps us build your workout.": "يساعدنا هذا في بناء تمرينك.",
  "Which option best describes you?": "أي خيار يصفك على أفضل نحو؟",
  "This may help improve nutrition, sleep and water estimates. It doesn’t change your workouts.": "قد يساعد هذا في تحسين تقديرات التغذية والنوم والماء. لا يغيّر تمارينك.",
