  "This will help with your nutrition guidance.": "سيساعد هذا في إرشادك الغذائي.",
  "What’s your current weight?": "كم وزنك الحالي؟",
  "This helps choose your starting weights and gives us a benchmark to track your progress.": "يساعد هذا في اختيار أوزانك الابتدائية ويمنحنا مرجعًا لتتبّع تقدمك.",
  "Do you have a goal weight?": "هل لديك وزن مستهدف؟",
  "This is so you can track your progress. You can change it later.": "هذا حتى تتمكن من تتبّع تقدمك. يمكنك تغييره لاحقًا.",
