  "This helps us decide your exercise selection and when someone may be able to help you.": "يساعدنا هذا في تحديد اختيار تمارينك ومتى قد يستطيع أحدهم مساعدتك.",
  "What equipment do you normally have access to?": "ما المعدات المتاحة لك عادةً؟",
