  "No other activity": "لا يوجد نشاط آخر",
  "Tell us about your activities": "أخبرنا عن أنشطتك",
  "When you do each one, and how demanding it usually is.": "متى تمارس كلًّا منها، ومدى صعوبتها عادةً.",
  "Skip, I’ll log these later": "تخطَّ، سأسجّلها لاحقًا",
  "Any dietary needs we should respect?": "هل من احتياجات غذائية ينبغي مراعاتها؟",
  "So the coach never suggests a food that does not fit. The app never sets calorie or macro targets.": "حتى لا يقترح المدرب طعامًا لا يناسبك. لا يحدد التطبيق أبدًا أهداف السعرات أو الماكروز.",
  "No restrictions": "لا قيود",
  "Are there any exercises you love?": "هل هناك تمارين تحبها؟",
  "We’ll prioritise them where they fit your plan.": "سنعطيها الأولوية حيثما تناسب خطتك.",
  "Any exercises you’d rather never do?": "هل هناك تمارين تفضّل ألّا تفعلها أبدًا؟",
  "We won’t include exercises you exclude.": "لن ندرج التمارين التي تستبعدها.",
  "What’s driving you?": "ما الذي يدفعك؟",
  "There’s no wrong answer. This helps make your experience feel more relevant to you.": "لا توجد إجابة خاطئة. يساعد هذا في جعل تجربتك أكثر ملاءمة لك.",
  "e.g. I want to feel fitter and build a routine I can keep": "مثال: أريد أن أشعر بلياقة أفضل وأبني روتينًا يمكنني الالتزام به",
  "Which movements cause discomfort?": "أي حركات تسبب لك انزعاجًا؟",
  "Optional. Select any that apply and add your own.": "اختياري. اختر ما ينطبق وأضف ما لديك.",
  "Which area is affected?": "أي منطقة متأثرة؟",
  "Pick the area your answer was about so we can train around it safely.": "اختر المنطقة التي كانت إجابتك عنها كي نتدرّب حولها بأمان.",
  "We’ll focus on progressive overload and enough volume to grow.": "سنركّز على الحمل التدريجي وحجم تدريب كافٍ للنمو.",
  "We’ll pair strength work with a plan that keeps you in a deficit.": "سنجمع بين تمارين القوة وخطة تبقيك في عجز حراري.",
  "We’ll build your plan around the big lifts and steady strength gains.": "سنبني خطتك حول الرفعات الكبرى ومكاسب القوة الثابتة.",
  "We’ll keep you moving with balanced, sustainable training.": "سنبقيك نشطًا بتدريب متوازن ومستدام.",
  "No problem at all": "لا مشكلة على الإطلاق",
  "We’ll give you a clear structure to follow from day one.": "سنمنحك هيكلًا واضحًا تتبعه من اليوم الأول.",
  "That’s worth working toward": "هذا يستحق العمل من أجله",
  "We’ll keep this front of mind as we build your plan.": "سنبقي هذا في مقدمة اهتماماتنا أثناء بناء خطتك.",
  "We’ll keep it balanced": "سنبقيه متوازنًا",
  "Your plan will train every major muscle group evenly.": "ستدرّب خطتك كل مجموعة عضلية رئيسية بالتساوي.",
  "Full gym access": "وصول كامل إلى الصالة",
  "We’ll make the most of the machines and free weights available to you.": "سنستفيد قدر الإمكان من الأجهزة والأوزان الحرة المتاحة لك.",
  "Built for home": "مصمم للمنزل",
  "Your plan will work with the space and kit you have at home.": "ستعمل خطتك بما لديك من مساحة ومعدات في المنزل.",
  "Bodyweight ready": "جاهز لتمارين وزن الجسم",
  "We’ll build effective sessions that need little to no equipment.": "سنصمم جلسات فعّالة تحتاج القليل من المعدات أو لا شيء.",
  "Balanced with your week": "متوازن مع أسبوعك",
  "We’ll shape your training around your everyday routine.": "سنشكّل تدريبك حول روتينك اليومي.",
  "Continue": "متابعة",
  "Skip": "تخطّي",
  "Nothing specific": "لا شيء محدد",
  "Almost there": "أوشكت على الانتهاء",
  "Save your personalised experience": "احفظ تجربتك المخصصة",
  "Create your account to save your answers, access your personalised training and track your progress.": "أنشئ حسابك لحفظ إجاباتك والوصول إلى تدريبك المخصص وتتبّع تقدمك.",
