  "Your StrengthHub experience is ready": "تجربتك في StrengthHub جاهزة",
  "Your plan": "خطتك",
  "A full week-by-week program unlocks once you save your experience.": "يُفتح برنامج كامل أسبوعًا بأسبوع بمجرد حفظ تجربتك.",
  "Shaped around your goals, schedule and preferences, {name}.": "مصمم وفق أهدافك وجدولك وتفضيلاتك، {name}.",
