  "When do you usually do this?": "متى تمارس هذا عادةً؟",
  "How demanding is it usually?": "ما مدى صعوبتها عادةً؟",
  "Tap to continue": "اضغط للمتابعة",
  "Understanding your training needs…": "جارٍ فهم احتياجاتك التدريبية…",
  "We have a clearer picture of what will work for you.": "أصبحت لدينا صورة أوضح لما سينجح معك.",
  "Extra care": "عناية إضافية",
  "About your {area}": "بخصوص {area}",
  "flagged area": "المنطقة المحددة",
  "You mentioned this may need extra care. Just a few quick questions so we can work around it and see how we can help.": "لقد ذكرت أن هذا قد يحتاج عناية إضافية. بضعة أسئلة سريعة فقط كي نتدرّب حوله ونرى كيف يمكننا المساعدة.",
  "StrengthHub provides general fitness information, not a medical assessment. This isn’t a diagnosis.": "يقدّم StrengthHub معلومات لياقة عامة، وليس تقييمًا طبيًا. هذا ليس تشخيصًا.",
  "I’ll come back later": "سأعود لاحقًا",
  "Thanks for your interest in StrengthHub": "شكرًا لاهتمامك بـ StrengthHub",
  "StrengthHub creates personalised training programs for people aged 18 and over. We can’t generate a program for you yet — but we’d love to have you when the time is right.": "ينشئ StrengthHub برامج تدريب مخصصة للأشخاص من عمر 18 عامًا فأكثر. لا يمكننا إنشاء برنامج لك بعد — لكن يسعدنا انضمامك في الوقت المناسب.",
  "In the meantime, staying active with sport and everyday movement is a great foundation.": "في هذه الأثناء، يُعدّ البقاء نشطًا بالرياضة والحركة اليومية أساسًا رائعًا.",
