  "A calm, step by step path into your first 90 days. Nothing here assumes you know anything yet.": "Một lộ trình nhẹ nhàng, từng bước cho 90 ngày đầu tiên của bạn. Không có gì ở đây giả định bạn đã biết trước điều gì.",
  "A group always needs an owner. Pick a member to hand the group to, and you'll leave once they take over.": "Một nhóm luôn cần chủ nhóm. Chọn một thành viên để bàn giao nhóm, và bạn sẽ rời đi khi họ tiếp quản.",
  "A planned rest day or a freeze token keeps your streak alive through an off day. You get 2 fresh freezes at each monthly reset, no guilt, no all-or-nothing.": "Một ngày nghỉ có kế hoạch hoặc một thẻ đóng băng giúp giữ chuỗi ngày của bạn qua một ngày nghỉ. Bạn nhận được 2 thẻ đóng băng mới mỗi lần reset hằng tháng, không áy náy, không được ăn cả ngã về không.",
