  "You're first in. New lifters land here every day. Invite a friend and climb together.": "Bạn là người đầu tiên tham gia. Mỗi ngày đều có người tập mới đến đây. Mời một người bạn và cùng nhau leo hạng.",
  "You're in the top tier. Hold your rank to stay in {tier}.": "Bạn đang ở bậc cao nhất. Giữ vững thứ hạng để ở lại {tier}.",
  "You're offline — changes are saved on this device and sync when you reconnect.": "Bạn đang ngoại tuyến — các thay đổi được lưu trên thiết bị này và đồng bộ khi bạn kết nối lại.",
  "You're placed in a league with others at your level, up to ~25 as it fills. Your score is your dashboard odometer, how consistently you hit your goals. It's about showing up, not how much you lift.": "Bạn được xếp vào một giải đấu với những người cùng trình độ, lên tới khoảng 25 người khi đầy. Điểm của bạn là đồng hồ nhất quán trên bảng điều khiển, thể hiện mức độ đều đặn bạn đạt mục tiêu. Điều quan trọng là có mặt, không phải bạn nâng được bao nhiêu.",
  "You're previewing Community. Claim a name to join groups and appear on leaderboards.": "Bạn đang xem trước Cộng đồng. Chọn một tên để tham gia nhóm và xuất hiện trên bảng xếp hạng.",
  "You're the only member, so leaving deletes this group for good.": "Bạn là thành viên duy nhất, nên rời đi sẽ xóa nhóm này vĩnh viễn.",
