  "You mentioned this may need extra care. Just a few quick questions so we can work around it and see how we can help.": "Bạn đã đề cập vùng này có thể cần chú ý thêm. Chỉ vài câu hỏi nhanh để chúng tôi tập tránh và xem có thể giúp thế nào.",
  "StrengthHub provides general fitness information, not a medical assessment. This isn’t a diagnosis.": "StrengthHub cung cấp thông tin thể hình chung, không phải đánh giá y tế. Đây không phải chẩn đoán.",
  "I’ll come back later": "Tôi sẽ quay lại sau",
  "Thanks for your interest in StrengthHub": "Cảm ơn bạn đã quan tâm đến StrengthHub",
  "StrengthHub creates personalised training programs for people aged 18 and over. We can’t generate a program for you yet — but we’d love to have you when the time is right.": "StrengthHub tạo chương trình tập cá nhân hóa cho người từ 18 tuổi trở lên. Chúng tôi chưa thể tạo chương trình cho bạn — nhưng rất mong được đón bạn khi đến thời điểm phù hợp.",
  "In the meantime, staying active with sport and everyday movement is a great foundation.": "Trong lúc đó, giữ vận động bằng thể thao và hoạt động hằng ngày là nền tảng tuyệt vời.",
